// ---------------------------------------------------------------------------------------------------------------------
// registration

void **__cudaRegisterFatBinary(void *fatCubin) {
    API_LOCK();
    auto *record = new FatbinRecord{.wrapper = fatCubin};
    g_fatbins.push_back(record);
    return reinterpret_cast<void **>(record);
}

void __cudaRegisterFatBinaryEnd(void **) {
}

void __cudaUnregisterFatBinary(void **) {
    // called from atexit handlers; modules are released with the process. Like CUDA at exit, wait for the GPU and
    // print the remaining device side printf output (once).
    API_LOCK();
    static bool flushed = false;
    if (flushed || !g_initialized || g_initError != cudaSuccess) {
        return;
    }
    flushed = true;
    for (size_t device = 0; device < g_devices.size(); device++) {
        if (g_devices[device].ctx != nullptr && libreCuCtxSetCurrent(g_devices[device].ctx) == 0) {
            synchronizeDevice(static_cast<int>(device));
            libreCuCtxFlushPrintf();
            warnAboutUnreportedKernelFailure(static_cast<int>(device));
        }
    }
    fflush(stdout);
}

char __cudaInitModule(void **) {
    return 1;
}

void __cudaRegisterFunction(void **fatCubinHandle, const char *hostFun, char *, const char *deviceName,
                            int, uint3 *, uint3 *, dim3 *, dim3 *, int *) {
    API_LOCK();
    g_kernels[hostFun] = new KernelRecord{
        .fatbin = reinterpret_cast<FatbinRecord *>(fatCubinHandle),
        .name = deviceName
    };
}

void __cudaRegisterVar(void **fatCubinHandle, char *hostVar, char *, const char *deviceName, int, size_t size,
                       int, int) {
    API_LOCK();
    g_vars[hostVar] = VarRecord{
        .fatbin = reinterpret_cast<FatbinRecord *>(fatCubinHandle),
        .name = deviceName,
        .size = size
    };
}

void __cudaRegisterManagedVar(void **fatCubinHandle, void **hostVarPtrAddress, char *, const char *deviceName,
                              int, size_t size, int, int) {
    API_LOCK();
    // __managed__ variables are accessed through a pointer that the runtime makes point to the variable;
    // since managed memory is CPU mapped device memory here, point it at the device variable once loaded
    g_vars[hostVarPtrAddress] = VarRecord{
        .fatbin = reinterpret_cast<FatbinRecord *>(fatCubinHandle),
        .name = deviceName,
        .size = size
    };
    RT_DEBUG("__managed__ variable %s is not supported", deviceName);
}

unsigned __cudaPushCallConfiguration(dim3 gridDim, dim3 blockDim, size_t sharedMem, struct CUstream_st *stream) {
    t_launchConfigs.push_back(LaunchConfig{gridDim, blockDim, sharedMem, stream});
    return 0;
}

cudaError_t __cudaPopCallConfiguration(dim3 *gridDim, dim3 *blockDim, size_t *sharedMem, void *stream) {
    if (t_launchConfigs.empty()) {
        return cudaErrorMissingConfiguration;
    }
    const LaunchConfig config = t_launchConfigs.back();
    t_launchConfigs.pop_back();
    *gridDim = config.grid;
    *blockDim = config.block;
    *sharedMem = config.sharedMem;
    *static_cast<cudaStream_t *>(stream) = config.stream;
    return cudaSuccess;
}

cudaError_t __cudaGetKernel(cudaKernel_t *kernel, const void *funcAddr) {
    API_LOCK();
    auto it = g_kernels.find(funcAddr);
    if (it == g_kernels.end()) {
        return recordError(cudaErrorInvalidDeviceFunction);
    }
    *kernel = reinterpret_cast<cudaKernel_t>(it->second);
    return cudaSuccess;
}

cudaError_t __cudaLaunchKernel(cudaKernel_t kernel, dim3 gridDim, dim3 blockDim, void **args, size_t sharedMem,
                               cudaStream_t stream) {
    API_LOCK();
    return launch(kernel, gridDim, blockDim, args, sharedMem, stream);
}

cudaError_t __cudaLaunchKernel_ptsz(cudaKernel_t kernel, dim3 gridDim, dim3 blockDim, void **args, size_t sharedMem,
                                    cudaStream_t stream) {
    API_LOCK();
    return launch(kernel, gridDim, blockDim, args, sharedMem, stream);
}

