// memory

cudaError_t cudaMalloc(void **devPtr, size_t size) {
    API_LOCK();
    if (devPtr == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    if (size == 0) {
        *devPtr = nullptr;
        return cudaSuccess;
    }
    LC_CHECK(libreCuMemAlloc(devPtr, size, false));
    return cudaSuccess;
}

cudaError_t cudaFree(void *devPtr) {
    API_LOCK();
    RT_CHECK(activateCurrentDevice());
    if (devPtr == nullptr) {
        return cudaSuccess;
    }
    // memory may still be in use by queued work
    RT_CHECK(synchronizeDevice(t_device));
    LC_CHECK(libreCuMemFree(devPtr));
    return cudaSuccess;
}

cudaError_t cudaMallocAsync(void **devPtr, size_t size, cudaStream_t) {
    return cudaMalloc(devPtr, size);
}

cudaError_t cudaFreeAsync(void *devPtr, cudaStream_t) {
    return cudaFree(devPtr);
}

cudaError_t cudaMallocPitch(void **devPtr, size_t *pitch, size_t width, size_t height) {
    if (pitch == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    *pitch = (width + 511) & ~size_t(511);
    return cudaMalloc(devPtr, *pitch * height);
}

cudaError_t cudaMallocManaged(void **devPtr, size_t size, unsigned int) {
    API_LOCK();
    if (devPtr == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    // device memory that is also mapped into the CPU address space (through BAR1) at the same address
    LC_CHECK(libreCuMemAlloc(devPtr, size, true));
    return cudaSuccess;
}

cudaError_t cudaMallocHost(void **ptr, size_t size) {
    API_LOCK();
    if (ptr == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    if (size == 0) {
        *ptr = nullptr;
        return cudaSuccess;
    }
    LC_CHECK(libreCuMemAllocHost(ptr, size));
    return cudaSuccess;
}

cudaError_t cudaHostAlloc(void **pHost, size_t size, unsigned int) {
    return cudaMallocHost(pHost, size);
}

cudaError_t cudaFreeHost(void *ptr) {
    API_LOCK();
    if (ptr == nullptr) {
        return cudaSuccess;
    }
    RT_CHECK(activateCurrentDevice());
    RT_CHECK(synchronizeDevice(t_device));
    LC_CHECK(libreCuMemFreeHost(ptr));
    return cudaSuccess;
}

cudaError_t cudaHostGetDevicePointer(void **pDevice, void *pHost, unsigned int) {
    API_LOCK();
    if (pDevice == nullptr || !libreCuMemIsPinnedHost(pHost)) {
        return recordError(cudaErrorInvalidValue);
    }
    // pinned host memory is mapped at the same address on the GPU
    *pDevice = pHost;
    return cudaSuccess;
}

cudaError_t cudaHostGetFlags(unsigned int *pFlags, void *pHost) {
    if (pFlags == nullptr || !libreCuMemIsPinnedHost(pHost)) {
        return recordError(cudaErrorInvalidValue);
    }
    *pFlags = cudaHostAllocMapped;
    return cudaSuccess;
}

cudaError_t cudaHostRegister(void *, size_t, unsigned int) {
    // registration is not needed for correctness: copies from unregistered memory are staged
    return cudaSuccess;
}

cudaError_t cudaHostUnregister(void *) {
    return cudaSuccess;
}

cudaError_t cudaMemGetInfo(size_t *free, size_t *total) {
    API_LOCK();
    RT_CHECK(activateCurrentDevice());
    LC_CHECK(libreCuMemGetInfo(free, total));
    return cudaSuccess;
}

cudaError_t cudaPointerGetAttributes(struct cudaPointerAttributes *attributes, const void *ptr) {
    API_LOCK();
    if (attributes == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    memset(attributes, 0, sizeof(*attributes));
    attributes->device = t_device;
    switch (classify(ptr)) {
        case PtrKind::DEVICE:
            attributes->type = cudaMemoryTypeDevice;
            attributes->devicePointer = const_cast<void *>(ptr);
            break;
        case PtrKind::PINNED:
            attributes->type = cudaMemoryTypeHost;
            attributes->devicePointer = const_cast<void *>(ptr);
            attributes->hostPointer = const_cast<void *>(ptr);
            break;
        case PtrKind::PAGEABLE:
            attributes->type = cudaMemoryTypeUnregistered;
            attributes->device = -2;
            attributes->hostPointer = const_cast<void *>(ptr);
            break;
    }
    return cudaSuccess;
}

cudaError_t cudaMemcpy(void *dst, const void *src, size_t count, enum cudaMemcpyKind) {
    API_LOCK();
    CUstream_st *stream{};
    RT_CHECK(resolveStream(nullptr, &stream));
    return memcpyOnStream(dst, src, count, stream, true);
}

cudaError_t cudaMemcpyAsync(void *dst, const void *src, size_t count, enum cudaMemcpyKind, cudaStream_t handle) {
    API_LOCK();
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    return memcpyOnStream(dst, src, count, stream, false);
}

cudaError_t cudaMemcpyPeer(void *dst, int, const void *src, int, size_t count) {
    return cudaMemcpy(dst, src, count, cudaMemcpyDefault);
}

static cudaError_t memcpy2D(void *dst, size_t dpitch, const void *src, size_t spitch, size_t width, size_t height,
                            cudaStream_t handle, bool synchronous) {
    API_LOCK();
    if (width > dpitch || width > spitch) {
        return recordError(cudaErrorInvalidPitchValue);
    }
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    if (dpitch == width && spitch == width) {
        return memcpyOnStream(dst, src, width * height, stream, synchronous);
    }
    for (size_t row = 0; row < height; row++) {
        RT_CHECK(memcpyOnStream(static_cast<uint8_t *>(dst) + row * dpitch,
                                static_cast<const uint8_t *>(src) + row * spitch, width, stream, false));
    }
    if (synchronous) {
        RT_CHECK(synchronizeStream(stream));
    }
    return cudaSuccess;
}

cudaError_t cudaMemcpy2D(void *dst, size_t dpitch, const void *src, size_t spitch, size_t width, size_t height,
                         enum cudaMemcpyKind) {
    return memcpy2D(dst, dpitch, src, spitch, width, height, nullptr, true);
}

cudaError_t cudaMemcpy2DAsync(void *dst, size_t dpitch, const void *src, size_t spitch, size_t width, size_t height,
                              enum cudaMemcpyKind, cudaStream_t stream) {
    return memcpy2D(dst, dpitch, src, spitch, width, height, stream, false);
}

cudaError_t cudaMemset(void *devPtr, int value, size_t count) {
    API_LOCK();
    CUstream_st *stream{};
    RT_CHECK(resolveStream(nullptr, &stream));
    // like CUDA, memset on device memory is asynchronous with respect to the host
    return memsetOnStream(devPtr, value, count, stream, false);
}

cudaError_t cudaMemsetAsync(void *devPtr, int value, size_t count, cudaStream_t handle) {
    API_LOCK();
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    return memsetOnStream(devPtr, value, count, stream, false);
}

cudaError_t cudaMemset2D(void *devPtr, size_t pitch, int value, size_t width, size_t height) {
    API_LOCK();
    CUstream_st *stream{};
    RT_CHECK(resolveStream(nullptr, &stream));
    for (size_t row = 0; row < height; row++) {
        RT_CHECK(memsetOnStream(static_cast<uint8_t *>(devPtr) + row * pitch, value, width, stream, false));
    }
    return cudaSuccess;
}

cudaError_t cudaGetSymbolAddress(void **devPtr, const void *symbol) {
    API_LOCK();
    return symbolAddress(symbol, devPtr, nullptr);
}

cudaError_t cudaGetSymbolSize(size_t *size, const void *symbol) {
    API_LOCK();
    return symbolAddress(symbol, nullptr, size);
}

static cudaError_t symbolCopy(const void *symbolDst, const void *symbolSrc, const void *src, void *dst, size_t count,
                              size_t offset, cudaStream_t handle, bool synchronous) {
    API_LOCK();
    void *dev_ptr{};
    size_t size{};
    RT_CHECK(symbolAddress(symbolDst != nullptr ? symbolDst : symbolSrc, &dev_ptr, &size));
    if (offset + count > size) {
        return recordError(cudaErrorInvalidValue);
    }
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    void *symbol_ptr = static_cast<uint8_t *>(dev_ptr) + offset;
    if (symbolDst != nullptr) {
        return memcpyOnStream(symbol_ptr, src, count, stream, synchronous);
    }
    return memcpyOnStream(dst, symbol_ptr, count, stream, synchronous);
}

cudaError_t cudaMemcpyToSymbol(const void *symbol, const void *src, size_t count, size_t offset, enum cudaMemcpyKind) {
    return symbolCopy(symbol, nullptr, src, nullptr, count, offset, nullptr, true);
}

cudaError_t cudaMemcpyFromSymbol(void *dst, const void *symbol, size_t count, size_t offset, enum cudaMemcpyKind) {
    return symbolCopy(nullptr, symbol, nullptr, dst, count, offset, nullptr, true);
}

cudaError_t cudaMemcpyToSymbolAsync(const void *symbol, const void *src, size_t count, size_t offset,
                                    enum cudaMemcpyKind, cudaStream_t stream) {
    return symbolCopy(symbol, nullptr, src, nullptr, count, offset, stream, false);
}

cudaError_t cudaMemcpyFromSymbolAsync(void *dst, const void *symbol, size_t count, size_t offset,
                                      enum cudaMemcpyKind, cudaStream_t stream) {
    return symbolCopy(nullptr, symbol, nullptr, dst, count, offset, stream, false);
}

// ---------------------------------------------------------------------------------------------------------------------
// streams

cudaError_t cudaStreamCreateWithFlags(cudaStream_t *pStream, unsigned int flags) {
    API_LOCK();
    if (pStream == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    CUstream_st *stream{};
    RT_CHECK(newStream(t_device, false, (flags & cudaStreamNonBlocking) == 0, &stream));
    g_devices[t_device].streams.push_back(stream);
    *pStream = stream;
    return cudaSuccess;
}

cudaError_t cudaStreamCreate(cudaStream_t *pStream) {
    return cudaStreamCreateWithFlags(pStream, cudaStreamDefault);
}

cudaError_t cudaStreamCreateWithPriority(cudaStream_t *pStream, unsigned int flags, int) {
    return cudaStreamCreateWithFlags(pStream, flags);
}

cudaError_t cudaStreamDestroy(cudaStream_t handle) {
    API_LOCK();
    if (handle == nullptr || handle == cudaStreamLegacy || handle == cudaStreamPerThread) {
        return recordError(cudaErrorInvalidResourceHandle);
    }
    RT_CHECK(activateDevice(handle->device));
    RT_CHECK(synchronizeStream(handle));
    LIFETIME_LOCK();
    auto &streams = g_devices[handle->device].streams;
    streams.erase(std::remove(streams.begin(), streams.end(), handle), streams.end());
    libreCuEventDestroy(handle->tail);
    libreCuStreamDestroy(handle->stream);
    delete handle;
    return cudaSuccess;
}

cudaError_t cudaStreamSynchronize(cudaStream_t handle) {
    API_LOCK();
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    if (stream->isDefault && (handle == nullptr || handle == cudaStreamLegacy)) {
        // the legacy default stream synchronizes with all blocking streams
        RT_CHECK(beginOperation(stream));
        RT_CHECK(endOperation(stream));
    }
    return synchronizeStream(stream);
}

cudaError_t cudaStreamQuery(cudaStream_t handle) {
    API_LOCK();
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    libreCudaStatus_t status = libreCuStreamQuery(stream->stream);
    return status == 0 ? cudaSuccess : (mapStatus(status) == cudaErrorNotReady ? cudaErrorNotReady
                                                                                 : recordError(mapStatus(status)));
}

cudaError_t cudaStreamWaitEvent(cudaStream_t handle, cudaEvent_t event, unsigned int) {
    API_LOCK();
    if (event == nullptr) {
        return recordError(cudaErrorInvalidResourceHandle);
    }
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    LC_CHECK(libreCuStreamWaitEvent(stream->stream, event->event));
    LC_CHECK(libreCuStreamCommence(stream->stream));
    return cudaSuccess;
}

cudaError_t cudaStreamGetFlags(cudaStream_t handle, unsigned int *flags) {
    API_LOCK();
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    if (flags != nullptr) {
        *flags = stream->blocking ? cudaStreamDefault : cudaStreamNonBlocking;
    }
    return cudaSuccess;
}

cudaError_t cudaStreamGetPriority(cudaStream_t, int *priority) {
    if (priority != nullptr) {
        *priority = 0;
    }
    return cudaSuccess;
}

cudaError_t cudaLaunchHostFunc(cudaStream_t handle, cudaHostFn_t fn, void *userData) {
    API_LOCK();
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    // executed synchronously once the preceding work of the stream completed
    RT_CHECK(synchronizeStream(stream));
    blocking([&] { fn(userData); });
    return cudaSuccess;
}

cudaError_t cudaStreamAddCallback(cudaStream_t handle, cudaStreamCallback_t callback, void *userData, unsigned int) {
    API_LOCK();
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    RT_CHECK(synchronizeStream(stream));
    blocking([&] { callback(handle, cudaSuccess, userData); });
    return cudaSuccess;
}

cudaError_t cudaStreamBeginCapture(cudaStream_t, enum cudaStreamCaptureMode) {
    return recordError(cudaErrorNotSupported);
}

cudaError_t cudaStreamIsCapturing(cudaStream_t, enum cudaStreamCaptureStatus *pCaptureStatus) {
    if (pCaptureStatus != nullptr) {
        *pCaptureStatus = cudaStreamCaptureStatusNone;
    }
    return cudaSuccess;
}

// ---------------------------------------------------------------------------------------------------------------------
// events

cudaError_t cudaEventCreateWithFlags(cudaEvent_t *event, unsigned int flags) {
    API_LOCK();
    if (event == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    LibreCUEvent lc_event{};
    LC_CHECK(libreCuEventCreate(&lc_event, flags));
    *event = new CUevent_st{.device = t_device, .event = lc_event, .flags = flags, .recorded = false};
    g_devices[t_device].events.insert(*event);
    return cudaSuccess;
}

cudaError_t cudaEventCreate(cudaEvent_t *event) {
    return cudaEventCreateWithFlags(event, cudaEventDefault);
}

cudaError_t cudaEventRecord(cudaEvent_t event, cudaStream_t handle) {
    API_LOCK();
    if (event == nullptr) {
        return recordError(cudaErrorInvalidResourceHandle);
    }
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    RT_CHECK(beginOperation(stream));
    LC_CHECK(libreCuEventRecord(event->event, stream->stream));
    event->recorded = true;
    return endOperation(stream);
}

cudaError_t cudaEventRecordWithFlags(cudaEvent_t event, cudaStream_t stream, unsigned int) {
    return cudaEventRecord(event, stream);
}

cudaError_t cudaEventSynchronize(cudaEvent_t event) {
    if (event == nullptr) {
        return recordError(cudaErrorInvalidResourceHandle);
    }
    // waiting does not need the lock; other threads may submit work meanwhile
    LC_CHECK(blocking([event] { return libreCuEventSynchronize(event->event); }));
    return cudaSuccess;
}

cudaError_t cudaEventQuery(cudaEvent_t event) {
    if (event == nullptr) {
        return recordError(cudaErrorInvalidResourceHandle);
    }
    return libreCuEventQuery(event->event) == 0 ? cudaSuccess : cudaErrorNotReady;
}

cudaError_t cudaEventElapsedTime(float *ms, cudaEvent_t start, cudaEvent_t end) {
    if (ms == nullptr || start == nullptr || end == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    if (!start->recorded || !end->recorded) {
        return recordError(cudaErrorInvalidResourceHandle);
    }
    if ((start->flags & cudaEventDisableTiming) || (end->flags & cudaEventDisableTiming)) {
        return recordError(cudaErrorInvalidResourceHandle);
    }
    libreCudaStatus_t status = libreCuEventElapsedTime(ms, start->event, end->event);
    if (status != 0) {
        return recordError(mapStatus(status));
    }
    return cudaSuccess;
}

cudaError_t cudaEventDestroy(cudaEvent_t event) {
    API_LOCK();
    if (event == nullptr) {
        return recordError(cudaErrorInvalidResourceHandle);
    }
    // the event's signal may still be released by queued work. A cudaDeviceReset already released it.
    if (event->event != nullptr) {
        blocking([event] { return libreCuEventSynchronize(event->event); });
    }
    LIFETIME_LOCK();
    g_devices[event->device].events.erase(event);
    if (event->event != nullptr) {
        libreCuEventDestroy(event->event);
    }
    delete event;
    return cudaSuccess;
}

